{
  "requirements": [
    {
      "target_id": "t0",
      "policy_source_id": "q7",
      "policy_quote": "You are a customer service agent that helps the user according to the <policy> provided below.",
      "requirement": "The assistant must only perform actions explicitly allowed by the policy and must not deviate from the defined scope of actions (e.g., sending messages, making tool calls)."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q8",
      "policy_quote": "You should not provide any information, knowledge, or procedures not provided by the user or available tools, or give subjective recommendations or comments.",
      "requirement": "The assistant must not provide unsupported information or subjective recommendations when performing the `refuel_data` action."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q8",
      "policy_quote": "You should only make one tool call at a time, and if you make a tool call, you should not respond to the user simultaneously.",
      "requirement": "The assistant must not make any other tool call or respond to the user while the `refuel_data` tool call is in progress."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q11",
      "policy_quote": "To refuel data you should: Ask them how much data they want to refuel, Confirm the price, Apply the refueled data to the line associated with the phone number the user provided.",
      "requirement": "The assistant must confirm the price per GB of data refueling with the user before applying the refueling, and the refueling must be applied to the line associated with the phone number provided by the user."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q11",
      "policy_quote": "The maximum amount of data that can be refueled is 2GB.",
      "requirement": "The amount of data refueled must not exceed 2 GB per refueling action."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q12",
      "policy_quote": "Make sure you try all the possible ways to resolve the user's issue before transferring to a human agent.",
      "requirement": "The assistant must ensure that all feasible troubleshooting steps (e.g., confirming data refueling) are attempted before considering a transfer to a human agent."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q16",
      "policy_quote": "If the user's data usage for a line associated with the phone number the user provided exceeds the plan's data limit, data connectivity will be lost. The user has 2 options: Change to a plan with more data, Add more data to the line by 'refueling' data at a price per GB specified by the plan.",
      "requirement": "The assistant must ensure that the user is informed of both options (changing the plan or refueling data) when their data limit is exceeded, and the refueling must be done at the plan's specified price per GB."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q16",
      "policy_quote": "If `check_network_mode_preference()` shows '2G' or '3G', guide the user to use `set_network_mode_preference(mode: str)` with the mode '4g_5g_preferred' to allow the phone to connect to 5G.",
      "requirement": "If the user's network mode preference is set to '2G' or '3G', the assistant must guide the user to switch to '4g_5g_preferred' mode to optimize data speed, **except** when the issue is resolved by refueling data."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q16",
      "policy_quote": "Refer to the general policy for guidelines on those options.",
      "requirement": "The assistant must follow the general policy guidelines for refueling data, including confirming the user's choice and ensuring the action aligns with the policy constraints."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q11",
      "policy_quote": "You can add more data to the line by 'refueling' data at a price per GB specified by the plan.",
      "requirement": "The refueling must be applied at the price per GB specified by the user's current plan."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q16",
      "policy_quote": "The user has 2 options: Change to a plan with more data, Add more data to the line by 'refueling' data at a price per GB specified by the plan.",
      "requirement": "The assistant must ensure the user is aware of both options (changing the plan or refueling data) and must not proceed with refueling unless the user explicitly chooses this option."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q11",
      "policy_quote": "The maximum amount of data that can be refueled is 2GB.",
      "requirement": "The refueling action must not exceed the 2 GB limit specified in the policy."
    }
  ]
}
